from typing import Dict

def store_info_in_header(
    info_type: str, 
    info_content: str, 
    header: Dict[str, str]
) -> Dict[str, str]:
    valid_types = {
        'lang': 'Accept-Language',
        'encoding': 'Accept-Encoding', 
        'cache': 'Cache-Control'
    }

    if info_type not in valid_types:
        return header.copy()

    updated_header = header.copy()
    updated_header[valid_types[info_type]] = info_content
    return updated_header

# Example usage and test cases
header = {}
print(store_info_in_header('lang', 'en-US', header))  # Should add Accept-Language: en-US
assert store_info_in_header('invalid', 'test', {}) == {}  # Test invalid type handling

def store_info_in_header(
    info_type: str, info_content: str, header: dict
) -> dict:
    valid_types = {'lang': 'Accept-Language', 
                   'encoding': 'Accept-Encoding', 
                   'cache': 'Cache-Control'}

    if info_type not in valid_types:
        return header.copy()

    updated_header = header.copy()
    updated_header[valid_types[info_type]] = info_content
    return updated_header

# Example usage and test cases
header = {}
print(store_info_in_header('lang', 'en-US', header))
assert store_info_in_header('invalid', 'test', {}) == {}

try:
    print(store_info_in_header(None, 'test', {}))
except Exception as e:
    print(f"Error: {e}")
